program='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # The patterned field is periodic along diagonals. Infer its shortest
    # period and color mapping from the unmasked cells.
    samples = [(r + c, value)
               for r, row in enumerate(grid)
               for c, value in enumerate(row)
               if r >= 3 and c >= 3 and value != 0]
    best = None
    for period in range(2, 10):
        groups = [Counter() for _ in range(period)]
        for diagonal, value in samples:
            groups[diagonal % period][value] += 1
        colors = [group.most_common(1)[0][0] if group else None
                  for group in groups]
        score = sum(group[color] for group, color in zip(groups, colors)
                    if color is not None) / max(1, len(samples))
        candidate = (score, -period, period, colors)
        if best is None or candidate[:2] > best[:2]:
            best = candidate
    _, _, period, colors = best

    output = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2:
                value = 1
            elif r == 2:
                value = 1 if c < 2 else 4
            elif c < 2:
                value = 1
            elif c == 2:
                value = 4
            else:
                value = colors[(r + c) % period]
            output[r][c] = value
    return output
'''
